#!/usr/bin/env bash
# Well Dweller Adaptive Aspect Patch v2.2 candidate - Linux / Steam Deck installer.
# Run from anywhere: ./WellDweller_Patch_Linux.sh ["/path/to/Well Dweller"]
# Default game folder: the folder containing this script.
set -euo pipefail
DIR="${1:-$(cd "$(dirname "$0")" && pwd)}"
EXE="$DIR/WellDweller.exe"; BAK="$DIR/WellDweller.exe.original"
WANT='dabebd9145ad005b2fde2d06d8c018fc58520f156900ad48f4a8dea6aa625cc2'; DONE='6cffda64da7f0178d0ce3f39bcf4e5694e64523344103bd2466b42e4df8d2c48'
sha() { sha256sum "$1" | cut -d' ' -f1; }
[ -f "$EXE" ] || { echo "ERROR: WellDweller.exe not found in $DIR"; exit 1; }
H=$(sha "$EXE")
[ "$H" = "$DONE" ] && { echo "Already patched (v2.2)."; exit 0; }
if [ -f "$BAK" ]; then
  [ "$(sha "$BAK")" = "$WANT" ] || { echo "ERROR: backup hash mismatch. Nothing changed."; exit 1; }
  SRC="$BAK"
elif [ "$H" = "$WANT" ]; then SRC="$EXE"
else echo "ERROR: unsupported WellDweller.exe ($H). Nothing changed."; exit 1; fi
TMP="$(mktemp "$DIR/WellDweller.patch.XXXXXX")"; trap 'rm -f "$TMP"' EXIT
cp "$SRC" "$TMP"
[ "$(sha "$TMP")" = "$WANT" ] || { echo "ERROR: source changed. Nothing changed."; exit 1; }
while read -r off hex; do
  [ -n "$off" ] || continue
  printf '%b' "$(echo "$hex" | sed 's/../\\x&/g')" | dd of="$TMP" bs=1 seek="$off" conv=notrunc status=none
done <<'PATCHES'
